import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Skeleton } from '@/components/ui/skeleton';
import { Brain, TrendingUp, Users, Zap, Clock, RefreshCw } from 'lucide-react';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import { useAIUsageDashboard, FUNCTION_COLORS, FUNCTION_LABELS } from '@/hooks/analytics/useAIUsageDashboard';
import type { TimeFilter } from '@/hooks/analytics/useAIUsageDashboard';
import { AIUsageLogsTab } from './AIUsageLogsTab';
import { AIUsageUsersTab } from './AIUsageUsersTab';

export function AIUsageDashboard() {
  const {
    logs, isLoading, isLoadingLogs, refetch, timeFilter, setTimeFilter,
    isError, error, logsError,
    logsPage, setLogsPage, logsTotal, profileMap, stats,
    cobertura, filtros, custoTexto,
    userUsage, functionUsage, timelineData,
  } = useAIUsageDashboard();

  const functionNames = Object.keys(FUNCTION_COLORS);
  const mensagemErro = error instanceof Error ? error.message : 'A consulta falhou. Tente novamente.';
  const picoChamadas = timelineData.reduce((max, ponto) => {
    const total = functionNames.reduce((soma, fn) => soma + (Number(ponto[fn]) || 0), 0);
    return Math.max(max, total);
  }, 0);

  return (
    <div className="space-y-6 w-full min-w-0">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-foreground flex items-center gap-2"><Brain className="w-6 h-6 text-primary" />Consumo de IA</h1>
          <p className="text-sm text-muted-foreground mt-1">Monitoramento de uso das funções de inteligência artificial por usuário</p>
        </div>
        <div className="flex items-center gap-2">
          <Select value={timeFilter} onValueChange={(v) => setTimeFilter(v as TimeFilter)}>
            <SelectTrigger className="w-[140px]" aria-label="Período"><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="1h">Última 1h</SelectItem><SelectItem value="6h">Últimas 6h</SelectItem>
              <SelectItem value="24h">Últimas 24h</SelectItem><SelectItem value="7d">Últimos 7 dias</SelectItem><SelectItem value="30d">Últimos 30 dias</SelectItem>
            </SelectContent>
          </Select>
          <Button variant="outline" size="icon" onClick={() => refetch()} aria-label="Atualizar dados de uso de IA">
            <RefreshCw className="w-4 h-4" aria-hidden="true" />
          </Button>
        </div>
      </div>

      {isError && (
        <Card role="alert">
          <CardContent className="py-8 text-center space-y-2">
            <p className="text-sm font-medium text-foreground">Não foi possível carregar o consumo de IA</p>
            <p className="text-xs text-muted-foreground">{mensagemErro}</p>
            <Button variant="outline" size="sm" onClick={() => refetch()}>Tentar de novo</Button>
          </CardContent>
        </Card>
      )}

      {isLoading ? (
        <div className="grid grid-cols-2 md:grid-cols-5 gap-4" aria-busy="true">
          {[0, 1, 2, 3, 4].map(i => (
            <Card key={i}>
              <CardContent className="pt-4 pb-3 space-y-2">
                <Skeleton className="h-3 w-20" delay={i * 80} />
                <Skeleton className="h-7 w-24" delay={i * 80} />
              </CardContent>
            </Card>
          ))}
          <span className="sr-only">Carregando consumo de IA…</span>
        </div>
      ) : !isError && (
      <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
        {[
          { icon: Zap, label: 'Chamadas', value: stats.totalCalls.toLocaleString() },
          { icon: TrendingUp, label: 'Tokens Total', value: stats.totalTokens.toLocaleString() },
          { icon: Users, label: 'Usuários Ativos', value: stats.uniqueUsers },
          { icon: Clock, label: 'Tempo Médio', value: `${stats.avgDuration}ms` },
        ].map(({ icon: Icon, label, value }) => (
          <Card key={label}><CardContent className="pt-4 pb-3"><div className="flex items-center gap-2 text-muted-foreground text-xs font-medium"><Icon className="w-3.5 h-3.5" /> {label}</div><p className="text-2xl font-bold text-foreground mt-1">{value}</p></CardContent></Card>
        ))}
        <Card><CardContent className="pt-4 pb-3"><div className="flex items-center gap-2 text-muted-foreground text-xs font-medium">❌ Erros</div><p className="text-2xl font-bold text-foreground mt-1">{stats.errorCount}{stats.totalCalls > 0 && <span className="text-xs text-muted-foreground ml-1">({((stats.errorCount / stats.totalCalls) * 100).toFixed(1)}%)</span>}</p></CardContent></Card>
      </div>
      )}

      <Tabs defaultValue="overview" className="space-y-4">
        <TabsList>
          <TabsTrigger value="overview">Visão Geral</TabsTrigger>
          <TabsTrigger value="users">Por Usuário</TabsTrigger>
          <TabsTrigger value="logs">Logs Detalhados</TabsTrigger>
        </TabsList>

        <TabsContent value="overview" className="space-y-4">
          {isLoading ? (
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-4" aria-busy="true">
              <Card className="lg:col-span-2"><CardContent className="pt-6"><Skeleton className="h-[280px] w-full" /></CardContent></Card>
              <Card><CardContent className="pt-6"><Skeleton className="h-[280px] w-full" /></CardContent></Card>
            </div>
          ) : isError ? (
            <Card><CardContent className="py-12 text-center text-muted-foreground text-sm">Os números e gráficos do período não puderam ser carregados.</CardContent></Card>
          ) : (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
            <Card className="lg:col-span-2">
              <CardHeader className="pb-2"><CardTitle className="text-sm font-medium">Chamadas ao Longo do Tempo</CardTitle></CardHeader>
              <CardContent>
                {timelineData.length > 0 && (
                  <p className="sr-only">
                    {`Gráfico de chamadas ao longo do tempo: ${timelineData.length} intervalo(s), maior intervalo com ${picoChamadas} chamada(s).`}
                  </p>
                )}
                {timelineData.length > 0 ? (
                  <ResponsiveContainer width="100%" height={280}>
                    <AreaChart data={timelineData}>
                      <CartesianGrid strokeDasharray="3 3" className="stroke-muted" />
                      <XAxis dataKey="time" fontSize={11} className="fill-muted-foreground" />
                      <YAxis fontSize={11} className="fill-muted-foreground" />
                      <Tooltip contentStyle={{ backgroundColor: 'hsl(var(--popover))', border: '1px solid hsl(var(--border))', borderRadius: '8px', color: 'hsl(var(--popover-foreground))' }} />
                      {functionNames.map(fn => <Area key={fn} type="monotone" dataKey={fn} stackId="1" fill={FUNCTION_COLORS[fn]} stroke={FUNCTION_COLORS[fn]} fillOpacity={0.6} name={FUNCTION_LABELS[fn] || fn} />)}
                    </AreaChart>
                  </ResponsiveContainer>
                ) : <div className="h-[280px] flex items-center justify-center text-muted-foreground text-sm">Nenhum dado no período selecionado</div>}
              </CardContent>
            </Card>

            <Card>
              <CardHeader className="pb-2"><CardTitle className="text-sm font-medium">Distribuição por Função</CardTitle></CardHeader>
              <CardContent>
                {functionUsage.length > 0 && (
                  <p className="sr-only">
                    {`Distribuição por função: ${functionUsage.map(f => `${FUNCTION_LABELS[f.name] || f.name} — ${f.tokens.toLocaleString()} tokens em ${f.calls} chamada(s)`).join('; ')}.`}
                  </p>
                )}
                {functionUsage.length > 0 ? (
                  <>
                    <ResponsiveContainer width="100%" height={180}>
                      <PieChart><Pie data={functionUsage} dataKey="tokens" nameKey="name" cx="50%" cy="50%" outerRadius={70} innerRadius={40}>{functionUsage.map((entry) => <Cell key={entry.name} fill={FUNCTION_COLORS[entry.name] || '#666'} />)}</Pie><Tooltip formatter={(v: any) => v.toLocaleString() + ' tokens'} /></PieChart>
                    </ResponsiveContainer>
                    <div className="space-y-1.5 mt-2">
                      {functionUsage.map(f => (
                        <div key={f.name} className="flex items-center justify-between text-xs">
                          <div className="flex items-center gap-1.5"><div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: FUNCTION_COLORS[f.name] || '#666' }} /><span className="text-muted-foreground">{FUNCTION_LABELS[f.name] || f.name}</span></div>
                          <span className="font-medium text-foreground">{f.calls}x</span>
                        </div>
                      ))}
                    </div>
                  </>
                ) : <div className="h-[280px] flex items-center justify-center text-muted-foreground text-sm">Sem dados</div>}
              </CardContent>
            </Card>
          </div>
          )}
        </TabsContent>

        <TabsContent value="users" className="space-y-4"><AIUsageUsersTab userUsage={userUsage} profileMap={profileMap as Map<string, { name?: string; email?: string }>} /></TabsContent>
        <TabsContent value="logs"><AIUsageLogsTab logs={logs} logsTotal={logsTotal} logsPage={logsPage} setLogsPage={setLogsPage} isLoading={isLoadingLogs} logsError={logsError} onRetry={refetch} profileMap={profileMap as Map<string, { name?: string; email?: string }>} /></TabsContent>
      </Tabs>

      {/* Sobre o que os números foram calculados: a agregação é da janela inteira
          no servidor, e o escopo é o de quem está vendo (RLS). Fica no fim de
          propósito — subir o bloco deslocaria linhas acima e o ratchet de lint
          leria o `any` pré-existente do gráfico como dívida nova. */}
      {cobertura && (
        <p className="text-xs text-muted-foreground">
          {cobertura.chamadas.toLocaleString()} chamadas na janela completa
          {cobertura.primeiro_registro && cobertura.ultimo_registro && (
            <> • de {new Date(cobertura.primeiro_registro).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' })} a {new Date(cobertura.ultimo_registro).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' })}</>
          )}
          {cobertura.chamadas_sem_tokens > 0 && <> • {cobertura.chamadas_sem_tokens.toLocaleString()} sem medição de tokens</>}
          {filtros?.balde_segundos ? <> • baldes de {Math.round(filtros.balde_segundos / 60)}min</> : null}
        </p>
      )}

      {/* Custo do período (IA-055): a tarifa aplicada é a VIGENTE no instante de
          cada registro, resolvida no servidor. Sem tarifa cadastrada ou sem
          moeda única, a tela diz isso — e não mostra zero, porque zero afirma
          "mediu e deu zero". */}
      {custoTexto && (
        <p className="text-xs text-muted-foreground">
          {custoTexto.medido
            ? <>custo medido {custoTexto.medido}</>
            : <>sem total de custo{custoTexto.variasMoedas ? ` (moedas ${custoTexto.variasMoedas} não são somadas)` : ' (nenhuma chamada com tarifa aplicável)'}</>}
          {custoTexto.interno && <> • interno {custoTexto.interno}</>}
          {custoTexto.reconciliado && <> • reconciliado {custoTexto.reconciliado}</>}
          {custoTexto.semTarifa > 0 && <> • {custoTexto.semTarifa.toLocaleString()} chamadas sem tarifa aplicável</>}
        </p>
      )}
    </div>
  );
}
